with feeds as (
    select HUB_LOSS_EVENT_HK, HUB_LOSS_EVENT_BK__CLAIM_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_loss_event__hm_hcm_extract__d33436606b') }}
